export const understandingSets = [
  { id: 'levy-u', title: 'Understanding & Application', book: 'levy', questions: levy },
  { id: 'bognar-u', title: 'Understanding & Application', book: 'bognar', questions: bognar },
  { id: 'emanuel-u', title: 'Understanding & Application', book: 'emanuel', questions: emanuel },
  { id: 'residency-u', title: 'Understanding & Application', book: 'residency', questions: residency },
  { id: 'gesda-u', title: 'Understanding & Application', book: 'gesda', questions: gesda },
].map((s) => ({
  ...s,
  questions: s.questions.map((q, i) => {
    // Rotate options deterministically so correct answers are spread across A-D.
    const shift = (i * 7 + 3) % 4
    const options = q.options.map((_, k) => q.options[(k + shift) % 4])
    return { ...q, options, answer: (q.answer - shift + 4) % 4, id: `${s.id}-${i + 1}`, n: i + 1 }
  }),
}))
